package com.pablo.controlgastos;

import android.app.*;import android.content.*;import android.database.Cursor;import android.graphics.*;import android.graphics.drawable.GradientDrawable;import android.hardware.biometrics.BiometricPrompt;import android.os.*;import android.provider.Settings;import android.view.*;import android.widget.*;import java.text.*;import java.util.*;

public class HomeActivity extends Activity {
 private static final int REQ_DEVICE_CREDENTIAL=7001;private ExpenseDb db;private LinearLayout list;private TextView gastos,ingresos,saldo,month;private boolean unlocked=false,authInProgress=false;private final DecimalFormat money=new DecimalFormat("#,##0.00");private final Calendar selectedMonth=Calendar.getInstance();private int BG,CARD,TEXT,MUTED,YELLOW,NAV;
 @Override public void onCreate(Bundle b){ThemePrefs.applyBaseTheme(this);super.onCreate(b);selectedMonth.set(Calendar.DAY_OF_MONTH,1);selectedMonth.set(Calendar.HOUR_OF_DAY,0);selectedMonth.set(Calendar.MINUTE,0);selectedMonth.set(Calendar.SECOND,0);selectedMonth.set(Calendar.MILLISECOND,0);initPalette();db=new ExpenseDb(this);migrateScreenshotSetting();applyScreenSecurity();build();}
 private void initPalette(){boolean l=ThemePrefs.isLight(this);BG=l?Color.rgb(246,248,249):Color.rgb(11,18,24);CARD=l?Color.WHITE:Color.rgb(22,32,41);TEXT=l?Color.rgb(31,38,44):Color.rgb(242,245,247);MUTED=l?Color.rgb(95,105,112):Color.rgb(158,169,178);YELLOW=l?Color.rgb(170,126,0):Color.rgb(255,207,52);NAV=l?Color.rgb(232,237,240):Color.rgb(17,25,32);}
 @Override protected void onResume(){super.onResume();applyScreenSecurity();refresh();getWindow().getDecorView().postDelayed(this::maybeAuthenticate,180);}private int dp(int n){return(int)(n*getResources().getDisplayMetrics().density+.5f);}private TextView tv(String s,int z,int c){TextView v=new TextView(this);v.setText(s);v.setTextSize(z);v.setTextColor(c);v.setPadding(dp(8),dp(6),dp(8),dp(6));return v;}private GradientDrawable bg(int c,int r){GradientDrawable g=new GradientDrawable();g.setColor(c);g.setCornerRadius(dp(r));return g;}private Button button(String s){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextColor(TEXT);b.setBackground(bg(CARD,14));return b;}
 private void build(){LinearLayout outer=new LinearLayout(this);outer.setOrientation(LinearLayout.VERTICAL);outer.setBackgroundColor(BG);outer.setOnApplyWindowInsetsListener((v,i)->{v.setPadding(0,i.getSystemWindowInsetTop()+dp(20),0,i.getSystemWindowInsetBottom());return i;});outer.requestApplyInsets();LinearLayout header=new LinearLayout(this);header.setOrientation(LinearLayout.VERTICAL);header.setPadding(dp(16),dp(14),dp(16),dp(4));LinearLayout tr=new LinearLayout(this);tr.setGravity(Gravity.CENTER_VERTICAL);TextView title=tv("ControlGastos",28,TEXT);title.setTypeface(Typeface.DEFAULT,Typeface.BOLD);tr.addView(title,new LinearLayout.LayoutParams(0,-2,1));Button help=button("? Ayuda");help.setOnClickListener(v->showHelp());tr.addView(help,new LinearLayout.LayoutParams(dp(94),dp(44)));header.addView(tr);LinearLayout mr=new LinearLayout(this);mr.setGravity(Gravity.CENTER_VERTICAL);Button prevMonth=button("‹");month=tv("",16,TEXT);month.setGravity(Gravity.CENTER);month.setTypeface(Typeface.DEFAULT,Typeface.BOLD);Button nextMonth=button("›");mr.addView(prevMonth,new LinearLayout.LayoutParams(dp(48),dp(42)));mr.addView(month,new LinearLayout.LayoutParams(0,dp(42),1));mr.addView(nextMonth,new LinearLayout.LayoutParams(dp(48),dp(42)));prevMonth.setOnClickListener(v->{selectedMonth.add(Calendar.MONTH,-1);refresh();});nextMonth.setOnClickListener(v->{selectedMonth.add(Calendar.MONTH,1);refresh();});month.setOnClickListener(v->{Calendar n=Calendar.getInstance();selectedMonth.set(n.get(Calendar.YEAR),n.get(Calendar.MONTH),1,0,0,0);selectedMonth.set(Calendar.MILLISECOND,0);refresh();});header.addView(mr);outer.addView(header);LinearLayout sum=new LinearLayout(this);sum.setPadding(dp(12),dp(5),dp(12),dp(10));gastos=summaryCard("Gastos",Color.rgb(255,111,111));ingresos=summaryCard("Ingresos",Color.rgb(87,220,143));saldo=summaryCard("Saldo",Color.rgb(115,175,255));sum.addView(gastos,new LinearLayout.LayoutParams(0,dp(94),1));sum.addView(ingresos,new LinearLayout.LayoutParams(0,dp(94),1));sum.addView(saldo,new LinearLayout.LayoutParams(0,dp(94),1));outer.addView(sum);if(!notificationEnabled()){Button w=button("⚠ Activar lectura de notificaciones");w.setOnClickListener(v->openNotificationSettings());outer.addView(w);}TextView mov=tv("Movimientos",20,TEXT);mov.setTypeface(Typeface.DEFAULT,Typeface.BOLD);outer.addView(mov);ScrollView sc=new ScrollView(this);list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);list.setPadding(dp(12),0,dp(12),dp(10));sc.addView(list);outer.addView(sc,new LinearLayout.LayoutParams(-1,0,1));LinearLayout nav=new LinearLayout(this);nav.setBackgroundColor(NAV);Button inicio=navBtn("⌂\nInicio",true),graficos=navBtn("▥\nGráficos",false),add=navBtn("＋\nAgregar",true),imp=navBtn("⇧\nImportar",false),aj=navBtn("⚙\nAjustes",false);for(Button x:new Button[]{inicio,graficos,add,imp,aj})nav.addView(x,new LinearLayout.LayoutParams(0,dp(66),1));outer.addView(nav);graficos.setOnClickListener(v->startActivity(new Intent(this,AnalyticsActivity.class)));add.setOnClickListener(v->showAdd());imp.setOnClickListener(v->startActivity(new Intent(this,MainActivity.class)));aj.setOnClickListener(v->showSecuritySettings());setContentView(outer);}
 private TextView summaryCard(String l,int a){TextView v=tv(l+"\n$ 0",16,TEXT);v.setTypeface(Typeface.DEFAULT,Typeface.BOLD);GradientDrawable g=bg(CARD,14);g.setStroke(dp(1),a);v.setBackground(g);return v;}private Button navBtn(String s,boolean h){Button b=new Button(this);b.setText(s);b.setTextSize(12);b.setAllCaps(false);b.setTextColor(h?YELLOW:MUTED);b.setBackgroundColor(Color.TRANSPARENT);return b;}
 private void refresh(){db.materializeRecurring();list.removeAllViews();String mt=new SimpleDateFormat("MMMM yyyy",new Locale("es","UY")).format(selectedMonth.getTime());month.setText(mt.substring(0,1).toUpperCase()+mt.substring(1));Calendar a=(Calendar)selectedMonth.clone(),b=(Calendar)selectedMonth.clone();b.add(Calendar.MONTH,1);double in=0,out=0;Cursor c=db.getReadableDatabase().rawQuery("SELECT id,type,amount,currency,category,description,original_text,ts,source FROM tx WHERE ts>=? AND ts<? ORDER BY ts DESC",new String[]{String.valueOf(a.getTimeInMillis()),String.valueOf(b.getTimeInMillis())});ArrayList<Object[]> rows=new ArrayList<>();while(c.moveToNext()){String type=c.getString(1),cur=c.getString(3);double am=c.getDouble(2);if("UYU".equals(cur)){if("INGRESO".equals(type))in+=am;else out+=am;}rows.add(new Object[]{c.getLong(0),type,am,cur,c.getString(4),c.getString(5),c.getLong(7),c.getString(8)});}c.close();gastos.setText("Gastos\n$ "+money.format(out));ingresos.setText("Ingresos\n$ "+money.format(in));saldo.setText("Saldo\n$ "+money.format(in-out));SimpleDateFormat dkf=new SimpleDateFormat("yyyyMMdd",Locale.US),dl=new SimpleDateFormat("EEE, d 'de' MMM",new Locale("es","UY"));String last="";for(Object[]r:rows){long id=(Long)r[0],ts=(Long)r[6];String dk=dkf.format(new Date(ts));if(!dk.equals(last)){TextView h=tv(dl.format(new Date(ts)),15,MUTED);list.addView(h);last=dk;}String type=(String)r[1],cur=(String)r[3],cat=(String)r[4],desc=(String)r[5],src=(String)r[7];double am=(Double)r[2];LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(dp(12),dp(9),dp(10),dp(9));row.setBackground(bg(CARD,12));TextView d=tv(desc==null?"Sin descripción":desc,16,TEXT);row.addView(d,new LinearLayout.LayoutParams(0,-2,1));TextView amt=tv(("GASTO".equals(type)?"-":"+")+("USD".equals(cur)?"USD ":"$ ")+money.format(am),16,"GASTO".equals(type)?Color.rgb(220,75,75):Color.rgb(45,160,90));row.addView(amt);final long fid=id,fts=ts;final String ft=type,fc=cur,fcat=cat,fd=desc,fs=src;final double fa=am;row.setOnClickListener(v->showEdit(fid,ft,fa,fc,fcat,fd,fts,fs));row.setOnLongClickListener(v->{confirmDelete(fid,fd);return true;});list.addView(row);}if(rows.isEmpty()){TextView e=tv("No hay movimientos en "+month.getText()+".",15,MUTED);e.setGravity(Gravity.CENTER);list.addView(e);}}
 private void showAdd(){LinearLayout f=form();Spinner type=typeSpinner("GASTO");EditText amount=amountEdit(0);Spinner cur=currencySpinner("UYU");EditText desc=textEdit("Descripción",""),cat=textEdit("Categoría","");Calendar chosen=Calendar.getInstance();Button date=button("Fecha: "+new SimpleDateFormat("dd/MM/yyyy",Locale.US).format(chosen.getTime()));date.setOnClickListener(v->new DatePickerDialog(this,(x,y,m,d)->{chosen.set(y,m,d);date.setText("Fecha: "+new SimpleDateFormat("dd/MM/yyyy",Locale.US).format(chosen.getTime()));},chosen.get(Calendar.YEAR),chosen.get(Calendar.MONTH),chosen.get(Calendar.DAY_OF_MONTH)).show());f.addView(type);f.addView(amount);f.addView(cur);f.addView(desc);f.addView(cat);f.addView(date);new AlertDialog.Builder(this).setTitle("Nuevo movimiento").setView(f).setPositiveButton("Guardar",(d,w)->{try{double am=parseAmount(amount);String de=desc.getText().toString().trim(),ca=cat.getText().toString().trim();db.addTx(type.getSelectedItem().toString(),am,cur.getSelectedItem().toString(),ca.isEmpty()?"Sin categoría":ca,de.isEmpty()?"Sin descripción":de,"",chosen.getTimeInMillis(),"manual");refresh();}catch(Exception e){Toast.makeText(this,"Revisá el monto",Toast.LENGTH_LONG).show();}}).setNegativeButton("Cancelar",null).show();}
 private void showEdit(long id,String ct,double ca,String cc,String ccat,String cd,long cts,String source){LinearLayout f=form();Spinner type=typeSpinner(ct);EditText amount=amountEdit(ca);Spinner cur=currencySpinner(cc);EditText desc=textEdit("Descripción",cd),cat=textEdit("Categoría",ccat);Calendar chosen=Calendar.getInstance();chosen.setTimeInMillis(cts);Button date=button("Fecha: "+new SimpleDateFormat("dd/MM/yyyy",Locale.US).format(chosen.getTime()));date.setOnClickListener(v->new DatePickerDialog(this,(x,y,m,d)->{chosen.set(y,m,d);date.setText("Fecha: "+new SimpleDateFormat("dd/MM/yyyy",Locale.US).format(chosen.getTime()));},chosen.get(Calendar.YEAR),chosen.get(Calendar.MONTH),chosen.get(Calendar.DAY_OF_MONTH)).show());f.addView(type);f.addView(amount);f.addView(cur);f.addView(desc);f.addView(cat);f.addView(date);f.addView(tv("Origen: "+sourceLabel(source),13,MUTED));new AlertDialog.Builder(this).setTitle("Editar movimiento").setView(f).setPositiveButton("Guardar cambios",(d,w)->{try{db.updateTx(id,type.getSelectedItem().toString(),parseAmount(amount),cur.getSelectedItem().toString(),cat.getText().toString(),desc.getText().toString(),chosen.getTimeInMillis());refresh();}catch(Exception e){}}).setNeutralButton("Eliminar",(d,w)->confirmDelete(id,cd)).setNegativeButton("Cancelar",null).show();}
 private void confirmDelete(long id,String d){new AlertDialog.Builder(this).setTitle("Eliminar movimiento").setMessage(d).setPositiveButton("Eliminar",(x,w)->{db.deleteTx(id);refresh();}).setNegativeButton("Cancelar",null).show();}private LinearLayout form(){LinearLayout f=new LinearLayout(this);f.setOrientation(LinearLayout.VERTICAL);f.setPadding(dp(24),0,dp(24),0);return f;}private Spinner typeSpinner(String s){Spinner x=new Spinner(this);x.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"GASTO","INGRESO"}));x.setSelection("INGRESO".equals(s)?1:0);return x;}private Spinner currencySpinner(String s){Spinner x=new Spinner(this);x.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"UYU","USD"}));x.setSelection("USD".equals(s)?1:0);return x;}private EditText amountEdit(double v){EditText e=new EditText(this);e.setHint("Monto");e.setInputType(2|8192);if(v>0)e.setText(String.format(Locale.US,"%.2f",v));return e;}private EditText textEdit(String h,String v){EditText e=new EditText(this);e.setHint(h);if(v!=null)e.setText(v);return e;}private double parseAmount(EditText e){double v=Double.parseDouble(e.getText().toString().replace(',','.'));if(v<=0)throw new IllegalArgumentException();return v;}private String sourceLabel(String s){if(s==null)return"desconocido";if(s.toLowerCase().contains("paganza"))return"Paganza";if(s.startsWith("notificacion:"))return"Notificación";if(s.contains("xls"))return"Excel bancario";return s;}
 private SharedPreferences securityPrefs(){return getSharedPreferences("security",MODE_PRIVATE);}private boolean biometricLockEnabled(){return securityPrefs().getBoolean("biometric_lock",false);}private boolean screenshotsBlocked(){return securityPrefs().getBoolean("block_screenshots",false);}private void migrateScreenshotSetting(){SharedPreferences p=securityPrefs();if(!p.getBoolean("screenshots_default_migrated_v142",false))p.edit().putBoolean("block_screenshots",false).putBoolean("screenshots_default_migrated_v142",true).apply();}private void applyScreenSecurity(){if(screenshotsBlocked())getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE);else getWindow().clearFlags(WindowManager.LayoutParams.FLAG_SECURE);}
 private void showSecuritySettings(){LinearLayout f=form();Switch light=new Switch(this);light.setText("Modo claro");light.setChecked(ThemePrefs.isLight(this));Switch bio=new Switch(this);bio.setText("Bloquear al abrir con huella/biometría");bio.setChecked(biometricLockEnabled());Switch shots=new Switch(this);shots.setText("Bloquear capturas y vista en recientes");shots.setChecked(screenshotsBlocked());Button tools=button("Importar · reglas · recurrentes · exportar");tools.setOnClickListener(v->startActivity(new Intent(this,MainActivity.class)));f.addView(light);f.addView(bio);f.addView(shots);f.addView(tools);new AlertDialog.Builder(this).setTitle("Configuración").setView(f).setPositiveButton("Guardar",(d,w)->{boolean was=biometricLockEnabled(),tc=ThemePrefs.isLight(this)!=light.isChecked();ThemePrefs.setLight(this,light.isChecked());securityPrefs().edit().putBoolean("biometric_lock",bio.isChecked()).putBoolean("block_screenshots",shots.isChecked()).apply();applyScreenSecurity();if(tc){recreate();return;}if(bio.isChecked()&&!was){unlocked=false;getWindow().getDecorView().postDelayed(this::maybeAuthenticate,250);}else if(!bio.isChecked())unlocked=true;}).setNegativeButton("Cancelar",null).show();}
 private void maybeAuthenticate(){if(!biometricLockEnabled()||unlocked||authInProgress||isFinishing())return;authInProgress=true;if(Build.VERSION.SDK_INT>=28)authenticateBiometric();else authenticateDeviceCredential();}private void authenticateBiometric(){try{CancellationSignal c=new CancellationSignal();BiometricPrompt p=new BiometricPrompt.Builder(this).setTitle("Desbloquear ControlGastos").setSubtitle("Confirmá tu identidad para ver tus movimientos").setNegativeButton("Cancelar",getMainExecutor(),(d,w)->{authInProgress=false;finish();}).build();p.authenticate(c,getMainExecutor(),new BiometricPrompt.AuthenticationCallback(){@Override public void onAuthenticationSucceeded(BiometricPrompt.AuthenticationResult r){authInProgress=false;unlocked=true;}@Override public void onAuthenticationError(int c,CharSequence m){authInProgress=false;}});}catch(Exception e){authInProgress=false;authenticateDeviceCredential();}}private void authenticateDeviceCredential(){try{KeyguardManager km=(KeyguardManager)getSystemService(KEYGUARD_SERVICE);if(km==null||!km.isKeyguardSecure()){authInProgress=false;return;}Intent i=km.createConfirmDeviceCredentialIntent("Desbloquear ControlGastos","Confirmá tu identidad para continuar");startActivityForResult(i,REQ_DEVICE_CREDENTIAL);}catch(Exception e){authInProgress=false;}}@Override protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(r==REQ_DEVICE_CREDENTIAL){authInProgress=false;if(c==RESULT_OK)unlocked=true;else finish();}}
 private void showHelp(){ScrollView sc=new ScrollView(this);TextView t=tv("GUÍA PARA EMPEZAR\n\nControlGastos reúne tus gastos e ingresos en un solo lugar. Podés cargar movimientos manualmente, detectarlos desde notificaciones compatibles o importar el Excel de eBROU. No necesitás ingresar tu usuario ni contraseña bancaria.\n\nINICIO Y CAMBIO DE MES\nLa pantalla Inicio muestra los totales y movimientos del mes seleccionado. Usá las flechas ‹ y › junto al nombre del mes para ir al mes anterior o siguiente. Tocá el nombre del mes para volver rápidamente al mes actual.\n\n1. PRIMERA CONFIGURACIÓN\nPara registrar compras automáticamente, tocá ‘Activar lectura de notificaciones’ y autorizá a ControlGastos. En algunos Android instalados mediante APK puede ser necesario habilitar primero los ajustes restringidos desde la información de la aplicación. Una vez autorizado, ControlGastos puede reconocer notificaciones compatibles de BROU/eBROU, Paganza y las reglas que configures.\n\n2. QUÉ ES LA LISTA BLANCA\nEntrá en Ajustes → Importar · reglas · recurrentes · exportar → Palabras y categorías. Cada regla relaciona una palabra o frase con una categoría. Ejemplos: DISCO → Supermercado, ANCAP → Combustible, Farmashop → Salud, UTE → Servicios. Si el texto de un movimiento contiene esa palabra, ControlGastos puede asignarle esa categoría. No distingue mayúsculas/minúsculas ni tildes.\n\nLa lista es dinámica: no existe un cupo fijo de 50 reglas. Usá ‘+ Agregar regla’ para crear todas las que necesites y ‘×’ para eliminar una. Si escribís una categoría nueva, pasa a formar parte de las categorías disponibles.\n\n3. CATEGORÍAS Y ‘OTROS’\nLas categorías utilizadas en Gráficos y Presupuesto se obtienen de las categorías definidas en la lista blanca. ‘Otros’ tiene un significado especial: reúne los movimientos que no pudieron asociarse a ninguna regla/categoría. A medida que agregás o corregís reglas, los movimientos automáticos existentes pueden reclasificarse.\n\nDesde Gráficos → Categorías podés personalizar el color de cada categoría y también renombrarla. Al renombrarla, ControlGastos actualiza las reglas y movimientos relacionados para mantener todo consistente.\n\n4. QUÉ ES LA LISTA NEGRA\nLa lista negra evita registrar notificaciones que contienen determinadas palabras o frases, por ejemplo ‘rechazado’, ‘pendiente’ o ‘recordatorio’. Tiene prioridad sobre la lista blanca. También es dinámica: agregá o eliminá filas según necesites. Importante: la lista negra solo filtra notificaciones; nunca borra ni excluye movimientos reales del Excel bancario.\n\n5. IMPORTAR EL EXCEL DE EBROU\nDesde Importar podés seleccionar el archivo .xls original descargado de eBROU sin convertirlo a otro formato. ControlGastos lee fecha, descripción, débitos y créditos e intenta categorizar cada movimiento usando tu lista blanca. Los movimientos sin coincidencia quedan en ‘Otros’.\n\nLa app intenta evitar duplicados entre una compra detectada por notificación y la misma operación importada después desde el banco. Para conciliarlas compara importe, comercio/descripción y admite que la fecha bancaria pueda diferir algunos días.\n\n6. AGREGAR UN MOVIMIENTO MANUAL\nTocá ‘+ Agregar’ en la barra inferior. Elegí GASTO o INGRESO, monto, moneda, descripción, categoría y fecha. Esto sirve para efectivo o cualquier movimiento que no llegue por el banco.\n\n7. EDITAR O ELIMINAR\nEn Inicio, tocá un movimiento para editar tipo, monto, moneda, descripción, categoría o fecha. También podés eliminarlo. Una pulsación prolongada permite eliminar rápidamente.\n\n8. GRÁFICOS\nEn Gráficos tenés cuatro vistas: Categorías muestra cómo se reparte el gasto; Comercios muestra dónde gastaste; Evolución muestra los últimos 12 meses; Comparar permite enfrentar dos meses diferentes. Podés alternar entre vista mensual y anual cuando corresponda.\n\n9. PRESUPUESTO Y PROYECCIÓN\nEn Presupuesto y proyección aparecen tus categorías y los 12 meses del año. Cada celda compara el gasto real con lo presupuestado. Además muestra dos referencias obtenidas de tus movimientos reales: ‘Mes anterior’ indica cuánto gastaste en esa categoría el mes inmediatamente anterior, y ‘Año anterior’ indica cuánto gastaste en esa misma categoría durante el mismo mes del año anterior.\n\nAl tocar una celda podés usar directamente cualquiera de esas dos referencias como presupuesto, o escribir un importe propio. Por ejemplo, para octubre de 2026 podés tomar como referencia septiembre de 2026 o octubre de 2025. Las referencias son solo sugerencias: ControlGastos no cambia tu presupuesto hasta que vos elegís una o guardás un monto.\n\nTambién podés usar ‘Proyectar desde año anterior’ para completar de una vez los 12 meses usando los gastos reales del año anterior como base. Después podés editar cada mes individualmente. Los indicadores muestran si el gasto real está por encima, por debajo o en línea con el plan.\n\n10. MOVIMIENTOS RECURRENTES Y EXPORTACIÓN\nDesde las herramientas podés configurar movimientos recurrentes para gastos o ingresos que se repiten y exportar tus movimientos a CSV para analizarlos fuera de la app.\n\n11. SEGURIDAD Y APARIENCIA\nEn Ajustes podés elegir modo claro u oscuro, activar bloqueo biométrico y bloquear capturas de pantalla/vista en aplicaciones recientes.\n\nSI FALTA UNA COMPRA\nPrimero verificá que ControlGastos conserve el permiso de acceso a notificaciones. Después revisá la lista negra y la lista blanca. Si la operación igualmente no aparece, importar el Excel de eBROU es la forma más confiable de incorporarla.\n\nSI ALGO QUEDA EN ‘OTROS’\nMirá la descripción del movimiento y agregá a la lista blanca una palabra representativa del comercio, asignándole la categoría correcta. Esa regla también servirá para futuros movimientos similares.\n\nPRIVACIDAD\nLos movimientos y reglas se guardan localmente en ControlGastos. La aplicación no necesita tus credenciales bancarias para estas funciones.",15,TEXT);t.setPadding(dp(22),dp(10),dp(22),dp(18));sc.addView(t);new AlertDialog.Builder(this).setTitle("Ayuda · ControlGastos").setView(sc).setPositiveButton("Entendido",null).show();}
 private boolean notificationEnabled(){String e=Settings.Secure.getString(getContentResolver(),"enabled_notification_listeners");return e!=null&&e.contains(getPackageName());}private void openNotificationSettings(){try{startActivity(new Intent("android.settings.ACTION_NOTIFICATION_LISTENER_SETTINGS"));}catch(Exception ignored){}}
}
